<script setup lang="ts">import GModal from '../GModal/GModal.vue'; import type { TextContent } from '@/shared/types/components'; withDefaults(defineProps<{ open?: boolean; title?: TextContent; cancelLabel?: TextContent; confirmLabel?: TextContent }>(), { open: false, cancelLabel: () => ({ table: 'Common', textKey: '#CANCEL' }), confirmLabel: () => ({ table: 'Common', textKey: '#CONFIRM' }) }); const emit = defineEmits<{ confirm: []; cancel: []; 'update:open': [value: boolean] }>(); function cancel() { emit('cancel'); emit('update:open', false) } function confirm() { emit('confirm'); emit('update:open', false) }</script>
<template><GModal :open="open" :title="title" @update:open="emit('update:open', $event)"><div class="ew-confirm-dialog"><slot /><div class="ew-button-group"><button class="ew-button" type="button" @click="cancel">{{ cancelLabel }}</button><button class="ew-button" type="button" @click="confirm">{{ confirmLabel }}</button></div></div></GModal></template>
